import string
import uuid

DIGITS = string.digits + string.ascii_lowercase


def random_id():
    return uuid.uuid4().hex


def make_id(kind, n):
    if not isinstance(n, int) or isinstance(n, bool) or n < 0:
        raise ValueError('n must be a non-negative int')
    out = ''
    while True:
        n, r = divmod(n, 36)
        out = DIGITS[r] + out
        if n == 0:
            break
    return f'{kind.lower()}_{out.rjust(6, "0")}'

